1	package edgefleet
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"io"
11		"os"
12		"path/filepath"
13		"sort"
14		"syscall"
15		"time"
16	)
17	
18	// formatMarker identifies the on-disk file format version.
19	const formatMarker = "edgefleet-heartbeats-v1"
20	
21	// onlineWindow is the maximum age of the latest telemetry for a node to be
22	// considered online. Exactly onlineWindow is still online.
23	const onlineWindow = 60 * time.Second
24	
25	// CorruptError means the on-disk data failed parsing or verification. The
26	// store refuses to read or write while corruption is present.
27	type CorruptError struct {
28		Path string
29		Err  error
30	}
31	
32	func (e *CorruptError) Error() string {
33		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
34	}
35	
36	func (e *CorruptError) Unwrap() error { return e.Err }
37	
38	// IsCorrupt reports whether err is (or wraps) a CorruptError.
39	func IsCorrupt(err error) bool {
40		var ce *CorruptError
41		return errors.As(err, &ce)
42	}
43	
44	// nodeFile is the on-disk layout for one node.
45	type nodeFile struct {
46		Format   string      `json:"format"`
47		Checksum string      `json:"checksum"`
48		Records  []Heartbeat `json:"records"`
49	}
50	
51	// Store persists heartbeats as per-node JSON files under a data directory.
52	// Multiple Store instances (in the same or different processes) may safely
53	// access the same directory concurrently: a flock on the directory lock file
54	// serialises writers and lets queries take a shared lock, so a query never
55	// observes a partially written batch.
56	type Store struct {
57		dir      string
58		nodesDir string
59		lockPath string
60	}
61	
62	// OpenStore opens (and if needed creates) a data directory.
63	func OpenStore(dir string) (*Store, error) {
64		if err := os.MkdirAll(dir, 0o755); err != nil {
65			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
66		}
67		nodesDir := filepath.Join(dir, "nodes")
68		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
69			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
70		}
71		return &Store{dir: dir, nodesDir: nodesDir, lockPath: filepath.Join(dir, "lock")}, nil
72	}
73	
74	// Dir returns the data directory path.
75	func (s *Store) Dir() string { return s.dir }
76	
77	// nodePath maps a node id to its per-node file. Hex encoding keeps arbitrary
78	// node ids safe as filenames while remaining reversible.
79	func (s *Store) nodePath(nodeID string) string {
80		return filepath.Join(s.nodesDir, hex.EncodeToString([]byte(nodeID))+".json")
81	}
82	
83	// lock acquires the directory lock. Exclusive for writes, shared for reads.
84	// The returned closure releases the lock.
85	func (s *Store) lock(exclusive bool) (func(), error) {
86		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
87		if err != nil {
88			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
89		}
90		how := syscall.LOCK_SH
91		if exclusive {
92			how = syscall.LOCK_EX
93		}
94		if err := syscall.Flock(int(f.Fd()), how); err != nil {
95			f.Close()
96			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
97		}
98		return func() {
99			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
100			f.Close()
101		}, nil
102	}
103	
104	// checksumRecords returns a stable hash of the records. json.Marshal of a
105	// struct slice is deterministic for a given set of records.
106	func checksumRecords(records []Heartbeat) string {
107		data, _ := json.Marshal(records)
108		sum := sha256.Sum256(data)
109		return hex.EncodeToString(sum[:])
110	}
111	
112	// loadNodeFile reads and verifies the file for one node. A missing file means
113	// the node has no records (returns nil, nil). Any parse, checksum or
114	// structural failure is reported as a CorruptError.
115	//
116	// The file is decoded with the same strict rules as submit input: every
117	// telemetry field must be present, non-null and written once per record. A
118	// checksum that matches the zero-filled interpretation of a tampered record
119	// therefore cannot make a missing value look like real telemetry — the
120	// record is rejected before the checksum is consulted.
121	func loadNodeFile(path string) (*nodeFile, error) {
122		data, err := os.ReadFile(path)
123		if os.IsNotExist(err) {
124			return nil, nil
125		}
126		if err != nil {
127			return nil, &CorruptError{Path: path, Err: err}
128		}
129		nf, err := decodeStrictNodeFile(data)
130		if err != nil {
131			return nil, &CorruptError{Path: path, Err: err}
132		}
133		if nf.Format != formatMarker {
134			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
135		}
136		if err := validateStoredRecords(nf.Records); err != nil {
137			return nil, &CorruptError{Path: path, Err: err}
138		}
139		if got := checksumRecords(nf.Records); got != nf.Checksum {
140			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
141		}
142		return nf, nil
143	}
144	
145	// decodeStrictNodeFile parses the on-disk envelope without letting
146	// encoding/json defaults hide missing or duplicated data. The envelope has
147	// exactly three keys — format, checksum, records — each present, non-null and
148	// written once (a Unicode-escaped spelling of the same key still collides),
149	// and no other keys. Every element of records is decoded with
150	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
151	// field is an error naming the record and field rather than a zero value.
152	// Whitespace and key ordering carry no meaning and never cause a failure.
153	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
154		dec := json.NewDecoder(bytes.NewReader(data))
155		tok, err := dec.Token()
156		if err != nil {
157			return nil, fmt.Errorf("invalid JSON: %w", err)
158		}
159		if d, ok := tok.(json.Delim); !ok || d != '{' {
160			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
161		}
162	
163		var (
164			format   string
165			checksum string
166			records  []json.RawMessage
167	
168			seenFormat   bool
169			seenChecksum bool
170			seenRecords  bool
171		)
172		for dec.More() {
173			keyTok, err := dec.Token()
174			if err != nil {
175				return nil, fmt.Errorf("invalid JSON: %w", err)
176			}
177			key, ok := keyTok.(string)
178			if !ok {
179				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
180			}
181			var val json.RawMessage
182			if err := dec.Decode(&val); err != nil {
183				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
184			}
185			switch key {
186			case "format":
187				if seenFormat {
188					return nil, fmt.Errorf("duplicate envelope field %q", key)
189				}
190				seenFormat = true
191				if bytes.Equal(val, []byte("null")) {
192					return nil, fmt.Errorf("envelope field %q must not be null", key)
193				}
194				if err := json.Unmarshal(val, &format); err != nil {
195					return nil, fmt.Errorf("format must be a string: %w", err)
196				}
197			case "checksum":
198				if seenChecksum {
199					return nil, fmt.Errorf("duplicate envelope field %q", key)
200				}
201				seenChecksum = true
202				if bytes.Equal(val, []byte("null")) {
203					return nil, fmt.Errorf("envelope field %q must not be null", key)
204				}
205				if err := json.Unmarshal(val, &checksum); err != nil {
206					return nil, fmt.Errorf("checksum must be a string: %w", err)
207				}
208			case "records":
209				if seenRecords {
210					return nil, fmt.Errorf("duplicate envelope field %q", key)
211				}
212				seenRecords = true
213				if bytes.Equal(val, []byte("null")) {
214					return nil, fmt.Errorf("envelope field %q must not be null", key)
215				}
216				if err := json.Unmarshal(val, &records); err != nil {
217					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
218				}
219			default:
220				return nil, fmt.Errorf("unknown envelope field %q", key)
221			}
222		}
223		// Consume the closing brace.
224		if _, err := dec.Token(); err != nil {
225			return nil, fmt.Errorf("invalid JSON: %w", err)
226		}
227		// Nothing may follow the single envelope object.
228		if _, err := dec.Token(); err != io.EOF {
229			if err == nil {
230				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
231			}
232			return nil, fmt.Errorf("invalid JSON: %w", err)
233		}
234	
235		if !seenFormat {
236			return nil, fmt.Errorf("missing required envelope field %q", "format")
237		}
238		if !seenChecksum {
239			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
240		}
241		if !seenRecords {
242			return nil, fmt.Errorf("missing required envelope field %q", "records")
243		}
244	
245		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
246		for i, raw := range records {
247			h, err := decodeStrictHeartbeatObject(raw)
248			if err != nil {
249				return nil, fmt.Errorf("record %d: %w", i+1, err)
250			}
251			nf.Records = append(nf.Records, h)
252		}
253		return nf, nil
254	}
255	
256	// validateStoredRecords checks the structural invariants of a strictly
257	// decoded record set: sorted by ascending seq with no duplicate seq and
258	// valid field values. Position numbers are 1-based to match decoder errors.
259	func validateStoredRecords(records []Heartbeat) error {
260		for i, r := range records {
261			if r.NodeID == "" {
262				return fmt.Errorf("record %d: field %q must not be empty", i+1, "node")
263			}
264			if r.Seq <= 0 {
265				return fmt.Errorf("record %d: field %q must be a positive integer, got %d", i+1, "seq", r.Seq)
266			}
267			if r.Version == "" {
268				return fmt.Errorf("record %d: field %q must not be empty", i+1, "version")
269			}
270			if r.Height < 0 {
271				return fmt.Errorf("record %d: field %q must be >= 0, got %d", i+1, "height", r.Height)
272			}
273			if r.Missed < 0 {
274				return fmt.Errorf("record %d: field %q must be >= 0, got %d", i+1, "missed", r.Missed)
275			}
276			if r.CollectedAt.IsZero() {
277				return fmt.Errorf("record %d: field %q is missing or invalid", i+1, "collected_at")
278			}
279			if i > 0 && records[i-1].Seq >= r.Seq {
280				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
281			}
282		}
283		return nil
284	}
285	
286	// writeNodeFile persists records atomically: a temp file in the same
287	// directory is fsynced and renamed over the target, so a crash never leaves
288	// a half-written file.
289	func writeNodeFile(path string, records []Heartbeat) error {
290		if records == nil {
291			records = []Heartbeat{}
292		}
293		nf := nodeFile{
294			Format:   formatMarker,
295			Checksum: checksumRecords(records),
296			Records:  records,
297		}
298		data, err := json.MarshalIndent(nf, "", "  ")
299		if err != nil {
300			return err
301		}
302		return writeFileAtomic(path, data)
303	}
304	
305	func writeFileAtomic(path string, data []byte) error {
306		dir := filepath.Dir(path)
307		tmp, err := os.CreateTemp(dir, ".tmp-*")
308		if err != nil {
309			return err
310		}
311		tmpName := tmp.Name()
312		if _, err := tmp.Write(data); err != nil {
313			tmp.Close()
314			os.Remove(tmpName)
315			return err
316		}
317		if err := tmp.Sync(); err != nil {
318			tmp.Close()
319			os.Remove(tmpName)
320			return err
321		}
322		if err := tmp.Close(); err != nil {
323			os.Remove(tmpName)
324			return err
325		}
326		if err := os.Rename(tmpName, path); err != nil {
327			os.Remove(tmpName)
328			return err
329		}
330		// Best-effort fsync of the directory so the rename itself survives.
331		if d, err := os.Open(dir); err == nil {
332			d.Sync()
333			d.Close()
334		}
335		return nil
336	}
337	
338	// Submit persists a batch of heartbeats. The whole batch is validated and
339	// checked for duplicates/conflicts against stored data (and within the batch)
340	// before anything is written: a single invalid or conflicting record fails
341	// the batch with no changes. Duplicates are counted, not written. A
342	// successful return means the batch was durably persisted; a persistence
343	// failure is reported and previously queryable data is left intact.
344	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
345		if len(records) == 0 {
346			return 0, 0, fmt.Errorf("no heartbeat records provided")
347		}
348		for _, r := range records {
349			if err := ValidateHeartbeat(r, receiveTime); err != nil {
350				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
351			}
352		}
353	
354		unlock, err := s.lock(true)
355		if err != nil {
356			return 0, 0, err
357		}
358		defer unlock()
359	
360		// Deduplicate within the batch: same node+seq with equal fields counts
361		// as a duplicate; same node+seq with differing content is a conflict.
362		merged := make(map[string][]Heartbeat)
363		for _, r := range records {
364			list := merged[r.NodeID]
365			found := -1
366			for i, e := range list {
367				if e.Seq == r.Seq {
368					found = i
369					break
370				}
371			}
372			if found >= 0 {
373				if !list[found].Equal(r) {
374					return 0, 0, fmt.Errorf("conflicting records for node %q seq %d in batch: content differs", r.NodeID, r.Seq)
375				}
376				dupCount++
377				continue
378			}
379			merged[r.NodeID] = append(list, r)
380		}
381	
382		// Merge with stored data per node, collecting new file contents.
383		type update struct {
384			path    string
385			records []Heartbeat
386		}
387		var updates []update
388		for nodeID, batch := range merged {
389			path := s.nodePath(nodeID)
390			nf, err := loadNodeFile(path)
391			if err != nil {
392				return 0, 0, err
393			}
394			existing := []Heartbeat{}
395			if nf != nil {
396				existing = nf.Records
397			}
398			for _, r := range batch {
399				found := -1
400				for i, e := range existing {
401					if e.Seq == r.Seq {
402						found = i
403						break
404					}
405				}
406				if found >= 0 {
407					if !existing[found].Equal(r) {
408						return 0, 0, fmt.Errorf("conflicting record for node %q seq %d: content differs from stored record", nodeID, r.Seq)
409					}
410					dupCount++
411					continue
412				}
413				existing = append(existing, r)
414				newCount++
415			}
416			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
417			updates = append(updates, update{path: path, records: existing})
418		}
419	
420		// Persist. All updates are appends to previously verified data, so a
421		// failure here leaves every previously queryable record intact.
422		for _, u := range updates {
423			if err := writeNodeFile(u.path, u.records); err != nil {
424				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
425			}
426		}
427		return newCount, dupCount, nil
428	}
429	
430	// HealthResult is the health judgement for one node based on real telemetry.
431	type HealthResult struct {
432		NodeID      string
433		Status      string // "online", "offline", "notelemetry"
434		Seq         int64
435		CollectedAt time.Time
436		Version     string
437		Height      int64
438		Missed      int64 // cumulative missed duties at the latest heartbeat
439		Findings    []string
440	
441		// Baseline-relative missed duties, populated only by HealthSince.
442		// BaselineSeq is the seq of the heartbeat the query was anchored to;
443		// BaselineMissed is the cumulative count at that heartbeat. When
444		// NewMissedKnown is false the cumulative counter went backwards
445		// somewhere between the baseline and the latest record, so the number of
446		// newly missed duties cannot be derived; Findings then reports the
447		// rollback. Missed always remains the latest cumulative count.
448		BaselineSeq    int64
449		BaselineMissed int64
450		NewMissed      int64
451		NewMissedKnown bool
452	}
453	
454	// rollbackFinding warns that the cumulative missed-duty counter decreased
455	// between two adjacent saved heartbeats (typically a node counter reset),
456	// which makes the endpoint difference unusable as the new-miss count.
457	const rollbackFinding = "累计漏签数回退"
458	
459	// Health judges a node from its latest telemetry (the record with the
460	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
461	// query time earlier than the record's collection time is an error. Online
462	// status uses collection age against the query time: at most 60s is online
463	// (exactly 60s still online). Version skew and missed-duty rules follow the
464	// existing Evaluate rules.
465	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
466		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
467	}
468	
469	// HealthSince judges a node the same way Health does, but the missed-duty
470	// alarm is measured against a user-supplied baseline heartbeat instead of the
471	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
472	// already saved for the node: the latest heartbeat stays the record with the
473	// greatest seq, and new missed duties are the latest cumulative count minus
474	// the count at the baseline record. Only a strict excess over
475	// toleratedMisses alarms; equality does not.
476	//
477	// The baseline affects this query only: stored history is never modified.
478	// Seqs between the baseline and the latest may have gaps. If the cumulative
479	// count decreases between any two adjacent saved records in that interval the
480	// new count is reported as unknown (NewMissedKnown == false) and a rollback
481	// finding is emitted, even if the latest count later climbs back past the
482	// baseline; decreases before the baseline are irrelevant. A node without
483	// telemetry, an unknown baseline seq, or a baseline newer than the latest
484	// record is an error — no other record is substituted and the baseline count
485	// is never assumed to be zero.
486	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
487		if baselineSeq <= 0 {
488			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
489		}
490		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
491	}
492	
493	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
494		unlock, err := s.lock(false)
495		if err != nil {
496			return HealthResult{}, err
497		}
498		defer unlock()
499	
500		nf, err := loadNodeFile(s.nodePath(nodeID))
501		if err != nil {
502			return HealthResult{}, err
503		}
504		if nf == nil || len(nf.Records) == 0 {
505			if useBaseline {
506				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
507			}
508			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
509		}
510	
511		records := nf.Records // ascending seq, unique
512		latest := records[len(records)-1]
513	
514		if useBaseline {
515			if baselineSeq > latest.Seq {
516				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
517			}
518		}
519	
520		if at.Before(latest.CollectedAt) {
521			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
522				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
523		}
524	
525		age := at.Sub(latest.CollectedAt)
526		online := age <= onlineWindow
527	
528		findings := []string{}
529		if !online {
530			findings = append(findings, "offline")
531		}
532		if latest.Version != expectedVersion {
533			findings = append(findings, "version skew: "+latest.Version+" != "+expectedVersion)
534		}
535	
536		result := HealthResult{
537			NodeID:      nodeID,
538			Status:      "online",
539			Seq:         latest.Seq,
540			CollectedAt: latest.CollectedAt,
541			Version:     latest.Version,
542			Height:      latest.Height,
543			Missed:      latest.Missed,
544		}
545		if !online {
546			result.Status = "offline"
547		}
548	
549		if !useBaseline {
550			// Cumulative judgement: the current counter must strictly exceed the
551			// tolerance (mirrors Evaluate for callers that do not use a baseline).
552			node := Node{
553				ID:      nodeID,
554				Version: latest.Version,
555				Height:  latest.Height,
556				Missed:  int(latest.Missed),
557				Online:  online,
558			}
559			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
560			return result, nil
561		}
562	
563		baselineIdx := -1
564		for i, r := range records {
565			if r.Seq == baselineSeq {
566				baselineIdx = i
567				break
568			}
569		}
570		if baselineIdx < 0 {
571			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
572		}
573		baseline := records[baselineIdx]
574		result.BaselineSeq = baseline.Seq
575		result.BaselineMissed = baseline.Missed
576	
577		// Walk only saved records from the baseline up to the latest. Records are
578		// stored ascending by seq and seqs may legitimately have gaps, so any
579		// decrease between two adjacent saved records in this interval proves the
580		// cumulative counter reset somewhere in it; the endpoint difference alone
581		// must not be trusted even if the final count recovers.
582		rolledBack := false
583		for i := baselineIdx + 1; i < len(records); i++ {
584			if records[i].Missed < records[i-1].Missed {
585				rolledBack = true
586				break
587			}
588		}
589		if rolledBack {
590			result.NewMissedKnown = false
591			findings = append(findings, rollbackFinding)
592		} else {
593			result.NewMissedKnown = true
594			// No decrease was observed, so cumulative counts cannot have wrapped
595			// backwards within int64 range; the difference stays exact.
596			result.NewMissed = latest.Missed - baseline.Missed
597			if result.NewMissed > int64(toleratedMisses) {
598				findings = append(findings, "missed duties above tolerance")
599			}
600		}
601		result.Findings = findings
602		return result, nil
603	}
604	
605	// History returns all heartbeats for a node in ascending seq order, without
606	// duplicates. A node with no records returns an empty slice.
607	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
608		unlock, err := s.lock(false)
609		if err != nil {
610			return nil, err
611		}
612		defer unlock()
613	
614		nf, err := loadNodeFile(s.nodePath(nodeID))
615		if err != nil {
616			return nil, err
617		}
618		if nf == nil {
619			return []Heartbeat{}, nil
620		}
