159			{"duplicate version", `[{` + obj + `,"version":"2.0"}]`, "version"},
160			// A Unicode-escaped spelling of the same key counts as a duplicate.
161			{"duplicate missed via unicode escape", `[{` + obj + `,` + escMissed + `:1}]`, "missed"},
162			{"duplicate height via unicode escape", `[{` + obj + `,` + escHeight + `:101}]`, "height"},
163			{"duplicate node via unicode escape", `[{` + escNode + `:"n2",` + obj + `}]`, "node"},
