349	func TestStoredLegitimateFilesStayReadable(t *testing.T) {
350		dir := t.TempDir()
351		store, err := OpenStore(dir)
352		if err != nil {
353			t.Fatal(err)
354		}
355		receive := testBase
356	
357		// Explicit zero values are genuine telemetry and stay valid.
358		zeros := []Heartbeat{hb("z", 1, receive.Add(-time.Second), "1.0", 0, 0)}
359		// Large legal integers must survive exactly.
360		const big = int64(9223372036854775807)
361		bigs := []Heartbeat{hb("big", 1, receive.Add(-time.Second), "1.0", big, big-2)}
362		if _, _, err := store.Submit(append(append([]Heartbeat{}, zeros...), bigs...), receive); err != nil {
363			t.Fatal(err)
364		}
365	
366		r, err := store.Health("z", receive, "1.0", 0)
367		if err != nil {
368			t.Fatalf("explicit zeros must stay readable: %v", err)
369		}
370		if r.Height != 0 || r.Missed != 0 {
371			t.Errorf("zero telemetry misread: height=%d missed=%d", r.Height, r.Missed)
372		}
373		r, err = store.Health("big", receive, "1.0", 0)
374		if err != nil {
375			t.Fatalf("large integers must stay readable: %v", err)
376		}
377		if r.Height != big || r.Missed != big-2 {
378			t.Errorf("large integers lost precision: height=%d missed=%d", r.Height, r.Missed)
379		}
380	
381		// Reformat the file by hand: reordered envelope keys, reordered record
382		// keys, changed whitespace, trailing newline. Same checksum semantics.
383		path := store.nodePath("z")
384		raw := fmt.Sprintf("  {\n\t\"records\" : [ %s ],\n"+
385			"  \"checksum\":%q,\n\"format\":%q }\n",
386			`{"missed":0 , "height":0,"version":"1.0","collected_at":"2026-10-01T11:59:59Z","seq":1,"node":"z"}`,
387			checksumRecords(zeros), formatMarker)
388		if err := os.WriteFile(path, []byte(raw), 0o644); err != nil {
389			t.Fatal(err)
390		}
391		hist, err := store.History("z")
392		if err != nil {
393			t.Fatalf("whitespace/key-order changes must not look like corruption: %v", err)
394		}
395		if len(hist) != 1 || !hist[0].Equal(zeros[0]) {
396			t.Errorf("reformatted file misread: %+v", hist)
397		}
398	
399		// An empty record set with a correctly computed empty-set checksum is
400		// still a valid (telemetry-less) file.
401		emptyPath := store.nodePath("empty")
402		emptyContent := fmt.Sprintf(`{"format":%q,"checksum":%q,"records":[]}`,
403			formatMarker, checksumRecords([]Heartbeat{}))
404		if err := os.WriteFile(emptyPath, []byte(emptyContent), 0o644); err != nil {
405			t.Fatal(err)
406		}
407		hist, err = store.History("empty")
408		if err != nil {
409			t.Fatalf("empty records file must be readable: %v", err)
410		}
411		if len(hist) != 0 {
412			t.Errorf("expected no records, got %+v", hist)
413		}
414		r, err = store.Health("empty", receive, "1.0", 0)
415		if err != nil {
416			t.Fatalf("empty records file must behave as no telemetry: %v", err)
417		}
418		if r.Status != "notelemetry" {
419			t.Errorf("status=%q, want notelemetry", r.Status)
420		}
421	}
422	
423	// mustMarshal fails the test on JSON encoding errors.
424	func mustMarshal(t *testing.T, v any) []byte {
425		t.Helper()
426		b, err := json.Marshal(v)
427		if err != nil {
428			t.Fatal(err)
429		}
430		return b
431	}
